"""Fixed-budget unknown-column searches with marginal and inferred-stem penalties."""
import importlib.util, json, math, random, sys
from collections import Counter,defaultdict

sp=importlib.util.spec_from_file_location('old','/tmp/voy_piii_unknown.py');old=importlib.util.module_from_spec(sp);sp.loader.exec_module(old)
LAMBDA=3.; COLLISION=12.; SWEEPS=2; SHUFFLES=19; STEM_SUPPORT=4
BOOKS=('la_augustine','la_erasmus','la_vulg_daniel','la_patrick','la_vulg_esther_a')
SEEDS=(41,71,103);COLS=(10,24,131); MODES=('random','sequential'); KINDS=('real','iid','markov')

def stems(words):
    # Longest observed prefix of length >=2 supported by at least four distinct forms.
    types=set(words);pre=Counter()
    for w in types:
        for i in range(2,len(w)):pre[w[:i]]+=1
    ret={};ambiguous=set()
    for w in types:
        eligible=[w[:i] for i in range(2,len(w)) if pre[w[:i]]>=STEM_SUPPORT]
        if len(eligible)>1: ambiguous.add(w)
        ret[w]=max(eligible,key=len) if eligible else 'UNMATCHED:'+w
    return ret,sum(w in ambiguous for w in words)/len(words)

def penalty(n,p,N):return n*math.log(n/(N*p)) if n else 0.

def full_objective(seq,key,score,prior,groups,lam,collision):
    N=len(seq); counts=Counter(key[x] for x in seq); ps={c:(prior[c]+1)/(sum(prior.values())+len(old.alphabet)) for c in old.alphabet}
    ll=sum(score[key[a],key[b]] for a,b in zip(seq,seq[1:]))
    kl=sum(penalty(counts[c],ps[c],N) for c in old.alphabet)
    pairs=Counter((groups[x],v) for x,v in key.items()) if collision else Counter()
    return ll-lam*kl-collision*sum(n*(n-1)/2 for n in pairs.values())

def improve(seq,key,score,prior,groups,lam,collision):
    N=len(seq);occ=Counter(seq);letter=Counter();edge=Counter(zip(seq,seq[1:]));incoming=defaultdict(Counter);outgoing=defaultdict(Counter)
    for g,n in occ.items():letter[key[g]]+=n
    for (a,b),n in edge.items():outgoing[a][b]=n;incoming[b][a]=n
    prior_n=sum(prior.values())+len(old.alphabet);ps={c:(prior[c]+1)/prior_n for c in old.alphabet}
    assigned=Counter((groups[g],v) for g,v in key.items()) if collision else Counter()
    initial=full_objective(seq,key,score,prior,groups,lam,collision)
    for _ in range(SWEEPS):
      for g in sorted(key):
        prev=key[g];n=occ[g];group=groups[g]
        def local(c):
          likelihood=sum(q*score[c,c if h==g else key[h]] for h,q in outgoing[g].items())+sum(q*score[key[h],c] for h,q in incoming[g].items() if h!=g)
          if c==prev:return likelihood
          change=penalty(letter[prev]-n,ps[prev],N)+penalty(letter[c]+n,ps[c],N)-penalty(letter[prev],ps[prev],N)-penalty(letter[c],ps[c],N)
          # Removal saves assigned[prev]-1 pairs; insertion adds assigned[c] pairs.
          collchange=assigned[group,c]-(assigned[group,prev]-1) if collision else 0
          return likelihood-lam*change-collision*collchange
        chosen=max(old.alphabet,key=local)
        if chosen!=prev:
          letter[prev]-=n;letter[chosen]+=n
          if collision:assigned[group,prev]-=1;assigned[group,chosen]+=1
          key[g]=chosen
    final=full_objective(seq,key,score,prior,groups,lam,collision)
    assert final+1e-7>=initial,(initial,final)
    return key,initial,final

def summary(pred,truth,words,prior,score):
    n=len(truth);c=Counter(pred);pertype=defaultdict(list)
    for w,p,t in zip(words,pred,truth):pertype[w].append(p==t)
    ptotal=sum(prior.values())+len(old.alphabet)
    kl=sum((v/n)*math.log((v/n)/((prior[k]+1)/ptotal)) for k,v in c.items())
    return {'char_accuracy':sum(a==b for a,b in zip(pred,truth))/n,
            'macro_type_accuracy':sum(sum(v)/len(v) for v in pertype.values())/len(pertype),
            'alphabet_size':len(c),'max_letter_share':max(c.values())/n,'unigram_kl_nats':kl,
            'test_bigram_nll':-sum(score[a,b] for a,b in zip(pred,pred[1:]))/(n-1)}

def nulls(words,mapper,score,ncol,seed):
    rng=random.Random(seed);actual=old.loss(words,mapper,score,'a');glob=[];period=[]
    for _ in range(SHUFFLES):
      sh=list(words);rng.shuffle(sh);glob.append(old.loss(sh,mapper,score,'a'))
      sh=list(words)
      for p in range(ncol):
        ids=list(range(p,len(words),ncol));values=[words[i] for i in ids];rng.shuffle(values)
        for i,v in zip(ids,values):sh[i]=v
      period.append(old.loss(sh,mapper,score,'a'))
    return {'global_p':(1+sum(v<=actual for v in glob))/(SHUFFLES+1),
            'period_p':(1+sum(v<=actual for v in period))/(SHUFFLES+1)}

def one(book,ncol,mode,seed,kind):
    prior,rank,score=old.model(book);rng=random.Random(seed)
    plain=old.make_plain(random.Random(seed+100000),old.texts[book],kind,prior,score)
    cols=rng.sample(range(len(old.table)),ncol)
    chosen=[rng.randrange(ncol) if mode=='random' else i%ncol for i in range(len(plain))]
    pairs=[(cols[j],old.table[cols[j]][c]) for j,c in zip(chosen,plain)];words=[w for _,w in pairs]
    train=words[:old.TRAIN];test=words[old.TRAIN:];truth=plain[old.TRAIN:]
    sg=[w[-2:] for w in train];baseline=old.initial(sg,rank);uncon=old.optimize(sg,dict(baseline),score)
    group0={g:g for g in baseline};regular,oi,of=improve(sg,dict(baseline),score,prior,group0,LAMBDA,0)
    inferred,ambiguous=stems(train);initial={w:regular.get(w[-2:],rank[0]) for w in set(train)}
    wordskey,wi,wf=improve(train,initial,score,prior,inferred,LAMBDA,COLLISION)
    # An unseen word falls back to the separately learned suffix assignment.
    mapper={w:wordskey.get(w,regular.get(w[-2:],rank[0])) for w in set(test)}
    baseline_seq=[baseline.get(w[-2:],rank[0]) for w in test]
    uncon_seq=[uncon.get(w[-2:],rank[0]) for w in test]
    reg_seq=[regular.get(w[-2:],rank[0]) for w in test]
    stem_seq=[mapper[w] for w in test]
    truthmap=defaultdict(Counter)
    for w,t in zip(test,truth):truthmap[w][t]+=1
    upper=sum(max(v.values()) for v in truthmap.values())/len(test)
    # Column ambiguity measured only by the evaluator, never exposed to decoder.
    cgroups=defaultdict(Counter)
    for col,w in pairs[:old.TRAIN]:cgroups[inferred[w]][col]+=1
    purity=sum(max(c.values()) for c in cgroups.values())/old.TRAIN
    return {'book':book,'columns':ncol,'strategy':mode,'seed':seed,'kind':kind,
       'train_types':len(set(train)),'unseen_test_share':sum(w not in wordskey for w in test)/len(test),
       'inferred_stems':len(set(inferred.values())),'nested_prefix_ambiguity_share':ambiguous,'inferred_stem_majority_column_share':purity,
       'collision_limited_type_accuracy_ceiling':upper,
       'frequency_suffix':summary(baseline_seq,truth,test,prior,score),
       'unconstrained_suffix':summary(uncon_seq,truth,test,prior,score),
       'marginal_suffix':summary(reg_seq,truth,test,prior,score),
       'stem_penalized':summary(stem_seq,truth,test,prior,score),
       'suffix_objective_delta':of-oi,'stem_objective_delta':wf-wi,
       'stem_nulls':nulls(test,mapper,score,ncol,seed+700000)}

if __name__=='__main__':
    rows=[]
    for b in BOOKS:
      for n in COLS:
       for mode in MODES:
        for seed in SEEDS:
         for kind in KINDS:rows.append(one(b,n,mode,seed,kind))
      print('finished',b,file=sys.stderr,flush=True)
    print(json.dumps({'config':{'lambda':LAMBDA,'collision':COLLISION,'sweeps':SWEEPS,'shuffles':SHUFFLES,'stem_support':STEM_SUPPORT,'books':BOOKS,'seeds':SEEDS},'rows':rows},indent=2))

